// Markdown → 头条纯文本
let content = $input.first().json.content;

// 移除 Markdown 图片语法
content = content.replace(/!\[.*?\]\(.*?\)/g, '');
// 移除代码块
content = content.replace(/```[\s\S]*?```/g, '[代码示例]');
// 移除内联代码
content = content.replace(/`([^`]+)`/g, '$1');
// 标题转换
content = content.replace(/^### /gm, '');
content = content.replace(/^## /gm, '');
content = content.replace(/^# /gm, '');
// 加粗
content = content.replace(/\*\*(.*?)\*\*/g, '$1');
// 链接
content = content.replace(/\[(.*?)\]\(.*?\)/g, '$1');
// 表格清理
content = content.replace(/\|.*?\|/g, '');
// 多余空行
content = content.replace(/\n{3,}/g, '\n\n');
// 截断到头条限制（2000字）
if (content.length > 2000) {
  content = content.substring(0, 1997) + '...';
}

// 添加来源
const source = `\n\n—— 原文：${$input.first().json.link}`;

return {
  title: $input.first().json.title,
  content: content.substring(0, 2000 - source.length) + source
};
